(function () {
  'use strict';
  var RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
  var D2R = Math.PI / 180;
  var CAM_Z = 4.2, FOV = 40;
  var hasGSAP = !!(window.gsap && window.ScrollTrigger);

  /* Natural Earth country boundaries (50m) and a land mask, packed as base64.
     borders: line strings of int16 deltas in 0.01 degrees; dots: 2 bits per point of an even spiral
     (0 sea, 1 land, 2 India, 3 Namibia). */
  var WORLD = {"n":22000,"dots":"","borders":"","india":"","namibia":""};

  /* Globe poses per moment of the page.
     lat/lon: the point facing you. fx: horizontal offset as a fraction of half the screen width.
     s: scale. op: dot opacity. arc: how much of the Varanasi-Bengaluru line is drawn.
     hotel: how visible the Kamala Inn Grand marker is. */
  var HERO   = { lat: 20,  lon: 108, fx: 0.38,  s: 1.25, op: 0.8,  arc: 0, hotel: 0 };
  var PATH   = { lat: 25.32, lon: 55, fx: -0.55, s: 3.0, op: 0.95, arc: 1, hotel: 0 };
  var BEY_A  = { lat: 26.5, lon: 83.78, fx: 0.55, s: 2.2, op: 0.55, arc: 1, hotel: 0 };
  var BEY_B  = { lat: -22.56, lon: 17.08, fx: 0.55, s: 2.2, op: 0.55, arc: 1, hotel: 0 };
  var SPEECH = { lat: 10,  lon: 40,  fx: 0.4,   s: 1.4,  op: 0.7,  arc: 1, hotel: 0 };
  var PROJECTS = { lat: 35, lon: -10, fx: 0.0, s: 1.1, op: 0.4, arc: 1, hotel: 0 };
  var AIP    = { lat: 24,  lon: 84,  fx: 0.55,  s: 2.5,  op: 0.8,  arc: 1, hotel: 1 };
  var CLOSE  = { lat: 20,  lon: 78,  fx: 0,     s: 1.7,  op: 0.35, arc: 1, hotel: 0 };

  /* Globe colours per scene (the page colours themselves live in the CSS). */
  var SC = {
    hero:   { ink: 0x001a4d, dot: 0x8db8ff },
    path:   { ink: 0x050f26, dot: 0x8db8ff },
    sports: { ink: 0x062a21, dot: 0x9be3bf },
    kho:    { ink: 0x062a21, dot: 0x9be3bf },
    podium: { ink: 0x2b0e19, dot: 0xf6b3c6 },
    tt:     { ink: 0x062a35, dot: 0x8fdcec },
    mun:    { ink: 0x111b4d, dot: 0xb3c1ff },
    speech: { ink: 0x3d1a10, dot: 0xf6e08a },
    projects: { ink: 0x111111, dot: 0x4da3ff },
    ai:     { ink: 0x1a0d33, dot: 0xd9b3ff },
    close:  { ink: 0x030b1c, dot: 0x8db8ff }
  };

  var state = Object.assign({}, HERO);
  var cur = RM ? Object.assign({}, HERO) : Object.assign({}, HERO, { s: 0.5, op: 0 });
  
  var mouseX = 0, mouseY = 0, curMouseX = 0, curMouseY = 0;
  if (!RM) {
    window.addEventListener('pointermove', function(e) {
      mouseX = (e.clientX / window.innerWidth) * 2 - 1;
      mouseY = -(e.clientY / window.innerHeight) * 2 + 1;
    });
  }

  /* ------------------------------ 3D globe ------------------------------ */
  var canvas = document.getElementById('globe');
  var renderer = null;
  try {
    if (window.THREE) renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
  } catch (e) { renderer = null; }

  var scene, camera, world, globe, bodyMat, landMat, indMat, namMat, bordMat, hiInMat, hiNaMat, arcLine, arcMat;
  var ARC_N = 90, markers = [], tagDefs = [], target = null;

  function ll(lat, lon, r) {
    var la = lat * D2R, lo = lon * D2R;
    return new THREE.Vector3(Math.cos(la) * Math.cos(lo), Math.sin(la), -Math.cos(la) * Math.sin(lo)).multiplyScalar(r || 1);
  }
  function bytes(b64) { var s = atob(b64), u = new Uint8Array(s.length); for (var i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u; }

  // unpack boundary polylines into line segments on a sphere of the given radius
  function lineGeometry(b64, radius) {
    var u = bytes(b64), dv = new DataView(u.buffer), pos = 0;
    function rd() { var v = dv.getInt16(pos, true); pos += 2; return v; }
    var P = rd(), out = [];
    for (var l = 0; l < P; l++) {
      var n = rd(), x = rd(), y = rd(), px = null;
      for (var k = 0; k < n; k++) {
        if (k > 0) { x += rd(); y += rd(); }
        var la = (y / 100) * D2R, lo = (x / 100) * D2R, cl = Math.cos(la);
        var cx = cl * Math.cos(lo) * radius, cy = Math.sin(la) * radius, cz = -cl * Math.sin(lo) * radius;
        if (px) out.push(px[0], px[1], px[2], cx, cy, cz);
        px = [cx, cy, cz];
      }
    }
    var g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(out), 3));
    return g;
  }
  function pointsOf(arr, mat) {
    var g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(arr), 3));
    return new THREE.Points(g, mat);
  }

  function buildGlobe() {
    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(FOV, 1, 0.1, 50);
    camera.position.z = CAM_Z;
    world = new THREE.Group(); scene.add(world);
    globe = new THREE.Group(); world.add(globe);
    target = { ink: new THREE.Color(SC.hero.ink), dot: new THREE.Color(SC.hero.dot) };

    // Advanced textured earth with atmospheric glow
    var texLoader = new THREE.TextureLoader();
    var earthMap = texLoader.load('https://unpkg.com/three-globe/example/img/earth-blue-marble.jpg');
    var bumpMap = texLoader.load('https://unpkg.com/three-globe/example/img/earth-topology.png');
    var waterMap = texLoader.load('https://unpkg.com/three-globe/example/img/earth-water.png');

    bodyMat = new THREE.ShaderMaterial({
      uniforms: { 
        ink: { value: new THREE.Color(SC.hero.ink) }, 
        rim: { value: new THREE.Color(SC.hero.dot) }, 
        time: { value: 0 },
        tDiffuse: { value: earthMap },
        tBump: { value: bumpMap },
        tWater: { value: waterMap }
      },
      vertexShader: 'varying vec3 vN; varying vec3 vV; varying vec3 vPos; varying vec2 vUv; void main(){ vN = normalize(normalMatrix * normal); vec4 mv = modelViewMatrix * vec4(position, 1.0); vV = -mv.xyz; vPos = position; vUv = uv; gl_Position = projectionMatrix * mv; }',
      fragmentShader: `uniform vec3 ink; uniform vec3 rim; uniform float time; 
uniform sampler2D tDiffuse; uniform sampler2D tBump; uniform sampler2D tWater;
varying vec3 vN; varying vec3 vV; varying vec3 vPos; varying vec2 vUv;
float hash(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
float noise(vec3 x) { vec3 p = floor(x); vec3 f = fract(x); f = f*f*(3.0-2.0*f); return mix(mix(mix(hash(p+vec3(0,0,0)), hash(p+vec3(1,0,0)),f.x), mix(hash(p+vec3(0,1,0)), hash(p+vec3(1,1,0)),f.x),f.y), mix(mix(hash(p+vec3(0,0,1)), hash(p+vec3(1,0,1)),f.x), mix(hash(p+vec3(0,1,1)), hash(p+vec3(1,1,1)),f.x),f.y),f.z); }
float fbm(vec3 p) { float f = 0.0; f += 0.5000*noise(p); p*=2.02; f += 0.2500*noise(p); p*=2.03; f += 0.1250*noise(p); return f; }
void main(){
  float f = 1.0 - max(dot(normalize(vN), normalize(vV)), 0.0);
  float glow = pow(f, 2.6) * 0.5;
  float edge = smoothstep(0.93, 1.0, f) * 0.6;
  
  vec4 tex = texture2D(tDiffuse, vUv);
  float isWater = texture2D(tWater, vUv).r;
  float bump = texture2D(tBump, vUv).r;
  float luma = dot(tex.rgb, vec3(0.299, 0.587, 0.114));
  
  float n = fbm(vPos * 4.0 + time * 0.05);
  
  vec3 landColor = mix(ink * 0.7, ink * 2.2, luma + bump * 0.5);
  vec3 waterColor = mix(ink * 0.2, ink * 0.8, n * 0.5);
  vec3 baseColor = mix(landColor, waterColor, isWater);
  
  gl_FragColor = vec4(mix(baseColor, rim, glow + edge), 1.0);
}`
    });

    window.atmoMat = new THREE.ShaderMaterial({
      uniforms: { rim: { value: new THREE.Color(SC.hero.dot) } },
      vertexShader: 'varying vec3 vN; varying vec3 vV; void main(){ vN = normalize(normalMatrix * normal); vec4 mv = modelViewMatrix * vec4(position, 1.0); vV = -mv.xyz; gl_Position = projectionMatrix * mv; }',
      fragmentShader: 'uniform vec3 rim; varying vec3 vN; varying vec3 vV; void main(){ float f = 1.0 - max(dot(normalize(vN), normalize(vV)), 0.0); float glow = pow(f, 4.0); gl_FragColor = vec4(rim, glow * 0.55); }',
      transparent: true, blending: THREE.AdditiveBlending, side: THREE.BackSide, depthWrite: false
    });
    globe.add(new THREE.Mesh(new THREE.SphereGeometry(1.15, 64, 64), window.atmoMat));
    globe.add(new THREE.Mesh(new THREE.SphereGeometry(0.985, 64, 48), bodyMat));

    // round dot texture
    var c = document.createElement('canvas'); c.width = c.height = 64;
    var g2 = c.getContext('2d');
    g2.beginPath(); g2.arc(32, 32, 30, 0, Math.PI * 2); g2.fillStyle = '#fff'; g2.fill();
    var dotTex = new THREE.CanvasTexture(c);

    // land as dots: an even spiral over the sphere, kept only where the mask says land
    var codes = bytes(WORLD.dots), groups = [[], [], [], []];
    for (var i = 0; i < WORLD.n; i++) {
      var code = (codes[i >> 2] >> ((i & 3) * 2)) & 3;
      if (!code) continue;
      var yy = 1 - (i / (WORLD.n - 1)) * 2, rr = Math.sqrt(1 - yy * yy), th = Math.PI * (3 - Math.sqrt(5)) * i;
      groups[code].push(Math.cos(th) * rr, yy, Math.sin(th) * rr);
    }
    function dotMaterial(color, size) { return new THREE.PointsMaterial({ color: color, size: size, map: dotTex, alphaTest: 0.3, transparent: true, depthWrite: false }); }
    landMat = dotMaterial(SC.hero.dot, 0.032);
    indMat  = dotMaterial(0xe3b95c, 0.036);
    namMat  = dotMaterial(0xf5f7fb, 0.036);
    globe.add(pointsOf(groups[1], landMat), pointsOf(groups[2], indMat), pointsOf(groups[3], namMat));

    // every country boundary and coastline; India in gold and Namibia in white
    bordMat = new THREE.LineBasicMaterial({ color: SC.hero.dot, transparent: true, opacity: 0.5 });
    hiInMat = new THREE.LineBasicMaterial({ color: 0xe3b95c, transparent: true, opacity: 1 });
    hiNaMat = new THREE.LineBasicMaterial({ color: 0xf5f7fb, transparent: true, opacity: 1 });
    globe.add(new THREE.LineSegments(lineGeometry(WORLD.borders, 1.002), bordMat));
    globe.add(new THREE.LineSegments(lineGeometry(WORLD.india, 1.003), hiInMat));
    globe.add(new THREE.LineSegments(lineGeometry(WORLD.namibia, 1.003), hiNaMat));

    // places
    var places = [
      { name: 'varanasi',  lat: 25.32, lon: 82.97,  color: 0xe3b95c, hideWith: 'hotel' },
      { name: 'bengaluru', lat: 12.97, lon: 77.59,  color: 0xe3b95c },
      { name: 'namibia',   lat: -22.56, lon: 17.08, color: 0xf5f7fb },
      { name: 'hotel',     lat: 26.91, lon: 83.98,  color: 0xe3b95c, gate: true },
      { name: 'deoria',    lat: 26.50, lon: 83.78,  color: 0x9be3bf }
    ];
    var z = new THREE.Vector3(0, 0, 1), idx = 0;
    places.forEach(function (p) {
      var v = ll(p.lat, p.lon);
      var dot = new THREE.Mesh(new THREE.SphereGeometry(0.02, 14, 14), new THREE.MeshBasicMaterial({ color: p.color }));
      dot.position.copy(v).multiplyScalar(1.006); globe.add(dot);
      var ring = new THREE.Mesh(new THREE.RingGeometry(0.03, 0.037, 40), new THREE.MeshBasicMaterial({ color: p.color, transparent: true, side: THREE.DoubleSide, depthWrite: false }));
      ring.position.copy(v).multiplyScalar(1.006);
      ring.quaternion.setFromUnitVectors(z, v.clone().normalize());
      globe.add(ring);
      markers.push({ dot: dot, ring: ring, offset: idx++ * 0.33, gate: !!p.gate });
      var el = document.querySelector('.tag[data-place="' + p.name + '"]');
      if (el) {
        tagDefs.push({ el: el, v: v.clone(), gate: !!p.gate, hideWith: p.hideWith });
        el.onclick = function() {
          if (hasGSAP) {
            gsap.to(state, { lat: p.lat, lon: p.lon, s: 3.2, duration: 1.5, ease: "power2.out" });
          }
        };
      }
      p.v = v;
    });

    // Varanasi to Bengaluru, a lifted great-circle arc
    var a = places[0].v.clone().normalize(), b = places[1].v.clone().normalize();
    var ang = a.angleTo(b), s = Math.sin(ang), arc = [];
    for (var t = 0; t <= ARC_N; t++) {
      var f = t / ARC_N;
      var p2 = a.clone().multiplyScalar(Math.sin((1 - f) * ang) / s).add(b.clone().multiplyScalar(Math.sin(f * ang) / s));
      arc.push(p2.normalize().multiplyScalar(1 + 0.16 * Math.sin(Math.PI * f)));
    }
    arcMat = new THREE.LineBasicMaterial({ color: 0xe3b95c, transparent: true, opacity: 1 });
    arcLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints(arc), arcMat);
    globe.add(arcLine);

    // starfield for added depth and dynamic background
    var starGeo = new THREE.BufferGeometry();
    var starCount = 1000;
    var starPos = new Float32Array(starCount * 3);
    for(var i=0; i<starCount*3; i++) {
        starPos[i] = (Math.random() - 0.5) * 40;
    }
    starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
    var starMat = new THREE.PointsMaterial({color: 0xffffff, size: 0.03, transparent: true, opacity: 0.3, depthWrite: false});
    world.userData.stars = new THREE.Points(starGeo, starMat);
    world.add(world.userData.stars);
  }

  function resize() {
    if (!renderer) return;
    var w = window.innerWidth, h = window.innerHeight;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(w, h, false);
    camera.aspect = w / h; camera.updateProjectionMatrix();
    if (RM) draw(performance.now(), 1);
  }

  function draw(now, dt) {
    var w = window.innerWidth, h = window.innerHeight, small = w < 760, aspect = w / h;
    var halfW = Math.tan(FOV / 2 * D2R) * CAM_Z * aspect;
    var k = RM ? 1 : 1 - Math.pow(0.0008, dt);
    for (var key in state) cur[key] += (state[key] - cur[key]) * k;

    // colours ease towards the current scene
    var kc = RM ? 1 : 1 - Math.pow(0.02, dt);
    bodyMat.uniforms.ink.value.lerp(target.ink, kc);
    bodyMat.uniforms.rim.value.lerp(target.dot, kc);
    if (window.atmoMat) window.atmoMat.uniforms.rim.value.lerp(target.dot, kc);
    if(bodyMat.uniforms.time) bodyMat.uniforms.time.value = now * 0.001;
    landMat.color.lerp(target.dot, kc);
    bordMat.color.lerp(target.dot, kc);

    var effLon = cur.lon + (small && cur.fx < 0 ? cur.fx * -50 : 0);
    globe.rotation.set(cur.lat * D2R, -Math.PI / 2 - effLon * D2R + (RM ? 0 : Math.sin(now / 4000) * 0.04), 0);
    
    if (!RM) {
      curMouseX += (mouseX - curMouseX) * 0.05;
      curMouseY += (mouseY - curMouseY) * 0.05;
      world.rotation.x = curMouseY * 0.08;
      world.rotation.y = curMouseX * 0.08;
    }
    
    world.position.set(small ? 0 : cur.fx * halfW, small ? 0.55 : 0, 0);
    world.scale.setScalar(cur.s * Math.min(1, aspect * 0.85));

    if(world.userData.stars && !RM) {
        world.userData.stars.rotation.y = now * 0.00005;
        world.userData.stars.rotation.x = now * 0.00002;
    }

    var o = cur.op * (small ? 0.6 : 1);
    landMat.opacity = o;
    indMat.opacity = Math.min(1, o + 0.15);
    namMat.opacity = Math.min(1, o + 0.15);
    bordMat.opacity = Math.min(1, o * 0.6);
    hiInMat.opacity = Math.min(1, o + 0.1);
    hiNaMat.opacity = Math.min(1, o + 0.1);
    arcLine.geometry.setDrawRange(0, Math.max(0, Math.round(cur.arc * (ARC_N + 1))));
    arcMat.opacity = Math.min(1, cur.arc * 4) * (small ? 0.8 : 1);

    markers.forEach(function (m) {
      var gate = m.gate ? Math.max(0.001, cur.hotel) : 1;
      var ph = ((now / 1700) + m.offset) % 1;
      m.dot.scale.setScalar(gate);
      m.ring.scale.setScalar((1 + ph * 2.6) * gate);
      m.ring.material.opacity = (1 - ph) * 0.9 * Math.min(1, cur.op * 2) * (m.gate ? cur.hotel : 1);
    });

    renderer.render(scene, camera);

    if (!small) {
      var q = new THREE.Quaternion(); globe.getWorldQuaternion(q);
      tagDefs.forEach(function (t) {
        var facing = t.v.clone().applyQuaternion(q).z;
        var p = t.v.clone().applyMatrix4(globe.matrixWorld).project(camera);
        var x = (p.x * 0.5 + 0.5) * w, y = (-p.y * 0.5 + 0.5) * h;
        var gate = t.gate ? cur.hotel : (t.hideWith ? 1 - cur.hotel : 1);
        t.el.style.transform = 'translate(' + (x + 12).toFixed(1) + 'px,' + (y - 7).toFixed(1) + 'px)';
        t.el.style.opacity = Math.max(0, Math.min(1, (facing - 0.15) * 4)) * Math.min(1, cur.op * 2) * Math.max(0, Math.min(1, gate));
      });
    }
  }

  if (renderer) {
    buildGlobe();
    resize();
    window.addEventListener('resize', resize);
    if (RM) {
      draw(performance.now(), 1);
    } else {
      var last = performance.now();
      (function loop(now) {
        var dt = Math.min(0.05, (now - last) / 1000); last = now;
        draw(now, dt);
        requestAnimationFrame(loop);
      })(last);
    }
  }

  /* ------------------------------ scenes: page colour, globe colour, nav ------------------------------ */
  var links = document.querySelectorAll('[data-link]');
  var linkFor = { path: 'path', sports: 'beyond', kho: 'beyond', podium: 'beyond', tt: 'beyond', mun: 'beyond', speech: 'speech', projects: 'projects', ai: 'ai', close: 'close' };
  var activeScene = '';
  function setScene(name) {
    if (name === activeScene) return;
    activeScene = name;
    document.body.setAttribute('data-s', name);
    if (target && SC[name]) { target.ink.set(SC[name].ink); target.dot.set(SC[name].dot); }
    links.forEach(function (a) { a.setAttribute('aria-current', a.getAttribute('data-link') === linkFor[name] ? 'true' : 'false'); });
  }

  /* ------------------------------ scroll choreography ------------------------------ */
  if (!hasGSAP) { document.documentElement.classList.remove('anim'); return; }
  if (RM) { return; }

  window.__started = true;
  gsap.registerPlugin(ScrollTrigger);
  ScrollTrigger.config({ ignoreMobileResize: true });

  // the one orchestrated moment: the name rises in, then the details and portrait follow
  var intro = gsap.timeline({ defaults: { ease: 'power3.out' }, onComplete: function () { document.documentElement.classList.remove('anim'); } });
  intro.to('.line > span', { y: 0, yPercent: 0, duration: 1.1, stagger: 0.12 })
       .to('.rule', { opacity: 1, y: 0, duration: 0.6 }, '-=0.6')
       .to('.title', { opacity: 1, y: 0, duration: 0.7 }, '-=0.45')
       .to('.lede', { opacity: 1, y: 0, duration: 0.7 }, '-=0.5')
       .to('.facts', { opacity: 1, y: 0, duration: 0.7 }, '-=0.5');

  // progress line
  gsap.to('#prog', { scaleX: 1, ease: 'none', scrollTrigger: { start: 0, end: 'max', scrub: 0.2 } });

  // scene colour follows the section in view
  function sceneTrigger(sel, name) {
    ScrollTrigger.create({ trigger: sel, start: 'top 55%', end: 'bottom 55%', onToggle: function (self) { if (self.isActive) setScene(name); } });
  }
  setScene('hero');
  sceneTrigger('#hero', 'hero');
  sceneTrigger('#path', 'path');

  // globe moves between poses; created in page order so pin offsets stay correct
  function seg(from, to, trigger, start, end) {
    gsap.fromTo(state, Object.assign({}, from), Object.assign({}, to, {
      ease: 'none', immediateRender: false,
      scrollTrigger: { trigger: trigger, start: start, end: end, scrub: 1 }
    }));
  }
  seg(HERO, PATH, '#path', 'top 85%', 'top 25%');

  // education: the timeline line draws, the score meters fill
  gsap.fromTo('.spine', { scaleY: 0 }, { scaleY: 1, ease: 'none', scrollTrigger: { trigger: '.steps', start: 'top 70%', end: 'bottom 65%', scrub: true } });
  gsap.utils.toArray('.meter').forEach(function (m) {
    gsap.fromTo(m.querySelector('i'), { scaleX: 0 }, { scaleX: 1, ease: 'none', scrollTrigger: { trigger: m, start: 'top 90%', end: 'top 60%', scrub: 0.5 } });
  });

  seg(PATH, BEY_A, '#beyond', 'top 90%', 'top top');

  // sport: pin, slide sideways, run the Kho-Kho lane, turn the globe to Namibia
  var track = document.getElementById('track');
  var lane = document.getElementById('lane');
  var panels = gsap.utils.toArray('.panel:not(.intro)');
  var stops = [{ f: 0, name: 'sports' }];
  function dist() { return Math.max(0, track.scrollWidth - window.innerWidth); }

  function pickPanelScene(progress) {
    var best = 'sports', bd = Infinity;
    stops.forEach(function (s) { var d = Math.abs(progress - s.f); if (d < bd) { bd = d; best = s.name; } });
    setScene(best);
  }

  var tl = gsap.timeline({
    defaults: { ease: 'none', duration: 1 },
    scrollTrigger: {
      trigger: '#beyond', start: 'top top', end: function () { return '+=' + dist(); },
      pin: true, scrub: 0.6, anticipatePin: 1, invalidateOnRefresh: true,
      onUpdate: function (self) { pickPanelScene(self.progress); }
    }
  });
  tl.to(track, { x: function () { return -dist(); } }, 0)
    .to('#runner', { left: '100%' }, 0)
    .fromTo(state, Object.assign({}, BEY_A), Object.assign({}, BEY_B, { immediateRender: false }), 0);

  // cross-lanes on the Kho-Kho lane, one per result panel, where the runner meets it (in that panel's colour)
  function placeCrosses() {
    lane.querySelectorAll('.cross').forEach(function (c) { c.remove(); });
    stops = [{ f: 0, name: 'sports' }];
    var total = dist(); if (total <= 0) return;
    panels.forEach(function (p) {
      var centre = p.offsetLeft + p.offsetWidth / 2 - window.innerWidth / 2;
      var f = Math.min(1, Math.max(0, centre / total));
      stops.push({ f: f, name: p.getAttribute('data-s') });
      var c = document.createElement('span'); c.className = 'cross';
      c.style.left = (f * 100) + '%';
      c.style.background = getComputedStyle(p).getPropertyValue('--pa') || '#f5f7fb';
      lane.appendChild(c);
    });
  }
  placeCrosses();
  ScrollTrigger.addEventListener('refreshInit', placeCrosses);

  seg(BEY_B, SPEECH, '#speech', 'top 90%', 'top 40%');
  sceneTrigger('#speech', 'speech');

  seg(SPEECH, PROJECTS, '#projects', 'top 90%', 'top 40%');
  sceneTrigger('#projects', 'projects');

  seg(PROJECTS, AIP, '#ai', 'top 90%', 'top 40%');
  sceneTrigger('#ai', 'ai');
  seg(AIP, CLOSE, '#close', 'top 90%', 'top 40%');
  sceneTrigger('#close', 'close');

  var refresh = function () { ScrollTrigger.refresh(); };
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(refresh);
  window.addEventListener('load', refresh);
})();
// Ambient Particles
(function() {
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduce) return;

  const canvas = document.createElement('canvas');
  canvas.id = 'particles-canvas';
  document.body.prepend(canvas);
  const ctx = canvas.getContext('2d');
  let w, h;
  const dots = [];
  
  function resize() {
    w = canvas.width = window.innerWidth;
    h = canvas.height = window.innerHeight;
  }
  window.addEventListener('resize', resize);
  resize();

  for(let i = 0; i < 20; i++) {
    dots.push({
      x: Math.random() * w, y: Math.random() * h,
      vx: (Math.random() - 0.5) * 0.2, vy: (Math.random() - 0.5) * 0.2,
      r: Math.random() * 1.5 + 0.5,
      a: Math.random() * 0.5 + 0.1
    });
  }

  function draw() {
    ctx.clearRect(0, 0, w, h);
    dots.forEach(d => {
      d.x += d.vx; d.y += d.vy;
      if (d.x < 0) d.x = w; if (d.x > w) d.x = 0;
      if (d.y < 0) d.y = h; if (d.y > h) d.y = 0;
      ctx.beginPath();
      ctx.arc(d.x, d.y, d.r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(182, 255, 62, ${d.a})`;
      ctx.fill();
    });
    requestAnimationFrame(draw);
  }
  draw();
})();
/* =========================================================
   PREMIUM INTERACTION LAYER
   ========================================================= */
(function(){
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Custom cursor on pointer devices.
  if (!reduce && matchMedia('(pointer:fine)').matches) {
    const dot=document.getElementById('cursor-dot'), ring=document.getElementById('cursor-ring');
    let mx=innerWidth/2,my=innerHeight/2,rx=mx,ry=my;
    let cursorRunning = false;
    addEventListener('pointermove',e=>{
      mx=e.clientX;my=e.clientY;dot.style.left=mx+'px';dot.style.top=my+'px';
      if (!cursorRunning) {
        cursorRunning = true;
        cursorLoop();
      }
    });
    function cursorLoop(){
      rx += (mx-rx)*.16; ry += (my-ry)*.16;
      ring.style.left=rx+'px'; ring.style.top=ry+'px';
      if (Math.abs(mx-rx) < 0.1 && Math.abs(my-ry) < 0.1) {
        cursorRunning = false;
      } else {
        requestAnimationFrame(cursorLoop);
      }
    }
    document.querySelectorAll('a,button,.project,.project-card,.panel,.portrait,.tag,.chip,.sports li').forEach(el=>{
      el.addEventListener('mouseenter',()=>document.body.classList.add('cursor-hover'));
      el.addEventListener('mouseleave',()=>document.body.classList.remove('cursor-hover'));
    });
  }

  // Magnetic-ish buttons/links.
  if (!reduce && matchMedia('(pointer:fine)').matches) {
    document.querySelectorAll('.btn,.brand,.mail').forEach(el=>{
      el.addEventListener('pointermove',e=>{
        const r=el.getBoundingClientRect(), x=(e.clientX-r.left-r.width/2)*.08, y=(e.clientY-r.top-r.height/2)*.08;
        el.style.transform=`translate(${x}px,${y}px)`;
      });
      el.addEventListener('pointerleave',()=>el.style.transform='');
    });
  }

  // Scroll reveal for content blocks.
  const revealTargets=document.querySelectorAll('.path h2,.path .sub,.step,.speech-inner,.projects-inner,.ai-inner,.close>*');
  revealTargets.forEach(el=>el.classList.add('reveal'));
  if (!reduce && 'IntersectionObserver' in window) {
    const io=new IntersectionObserver(entries=>{
      entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target);}});
    },{threshold:.12,rootMargin:'0px 0px -7% 0px'});
    revealTargets.forEach(el=>io.observe(el));
  } else revealTargets.forEach(el=>el.classList.add('is-visible'));

  // 3D tilt / light tracking for cards.
  if (!reduce && matchMedia('(pointer:fine)').matches) {
    document.querySelectorAll('.project,.project-card,.portrait').forEach(card=>{
      card.addEventListener('pointermove',e=>{
        const r=card.getBoundingClientRect(), px=(e.clientX-r.left)/r.width, py=(e.clientY-r.top)/r.height;
        card.style.setProperty('--mx',(px*100)+'%'); card.style.setProperty('--my',(py*100)+'%');
        if(card.classList.contains('project-card') || card.classList.contains('project')){
          card.style.transform=`perspective(1100px) rotateX(${(py-.5)*-2.5}deg) rotateY(${(px-.5)*2.5}deg) translateY(-6px)`;
        }
      });
      card.addEventListener('pointerleave',()=>{card.style.transform='';});
    });
  }

  // Compact nav state + back-to-top.
  const nav=document.querySelector('.nav'), back=document.getElementById('backtop');
  addEventListener('scroll',()=>{
    const y=scrollY;
    nav?.classList.toggle('scrolled',y>30);
    back?.classList.toggle('show',y>900);
  },{passive:true});
  back?.addEventListener('click',()=>scrollTo({top:0,behavior:reduce?'auto':'smooth'}));
})();
